local DreamAdventuresMapDialog = Class("DreamAdventuresMapDialog")

--region lifecycle
function DreamAdventuresMapDialog:__init()
    self._siteNodeScrList = {}
    self._viewState = ViewState.MAP
    self._selectedSiteIndex = nil
    self._selectedStageIndex = nil
    self._questData = {}
    self._events = {}
end

function DreamAdventuresMapDialog:__delete()
    self._siteNodeScrList = nil
    self._viewState = nil
    self._selectedSiteIndex = nil
    self._selectedStageIndex = nil
    self._questData = nil
    self._events = nil
end

function DreamAdventuresMapDialog:Awake()
    self:RefreshSiteNode()
    CfUtils.SetActive(self.ChapterNode, false)
    
    CfUtils.PlayAnimation(self.Root, "ActivityDreamAdventureslStoryMap_Map", true)
end

function DreamAdventuresMapDialog:OnFocus(focus)
    if focus then
        if self:GetViewState() == ViewState.CHAPTER then
            CfUtils.SetTopCommonActive( true, true)
            local hpGoodsId = DreamAdventuresMgr:GetActivityHPId()
            CfUtils.RefreshTopGoods({hpGoodsId})
        end
    else
        local orderTracker = self.controller.gameObject:GetComponent(typeof(CS.Engine.UI.OrderTracker))
        if not IsNull(orderTracker) then
            orderTracker.addSortingOrder = 0
        end
    end
end

function DreamAdventuresMapDialog:OnInitialize()
    self:InitHandler()
    self:InitData()
    self:InitView()
end

function DreamAdventuresMapDialog:OnFinalize()
    CfUtils.ResetNavigatorCustomBackAction()
    for k, v in pairs(self._events) do
        Events.RemoveListener(k, v)
    end
    if not isNull(self._aniCo) then
        cs_coroutine.stop(self._aniCo)
    end
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end
--endregion lifecycle

--region init
function DreamAdventuresMapDialog:InitHandler()
    self._events[Constants.EventNames.EveryThingChangeEventName] = Events.AddListener(Constants.EventNames.EveryThingChangeEventName, Bind(self, self.ItemUpdateEventHandler))
    SetButtonAction(self.BtnClose, Bind(self, self.BtnCloseOnClickHandler))
    local btnClose = self.controller.transform:Find('BtnClose')
    if isNotNull(btnClose) then
        SetButtonAction(btnClose, Bind(self, self.BtnCloseOnClickHandler))
    end
    SetButtonAction(self.BtnGo, Bind(self, self.BtnGoOnClickHandler))
    for i, scr in ipairs(self._siteNodeScrList) do
        scr:SetOnClickCallback(Bind(self, self.SiteNodeOnClickHandler))
    end
end

function DreamAdventuresMapDialog:InitData()
    if DreamAdventuresMgr:GetNewQuestStatus() then
        local siteIndex, stageIndex = self:GetNewQuestStatus()
        if siteIndex and stageIndex then
            self:SetSelectedSiteIndex(siteIndex)
            self:SetSelectedStageIndex(stageIndex)
        end
    else
        local siteIndex, stageIndex = DreamAdventuresMgr:GetMapStatus()
        if siteIndex and stageIndex then
            self:SetSelectedSiteIndex(siteIndex)
            self:SetSelectedStageIndex(stageIndex)
        end
    end
    DreamAdventuresMgr:ClearMapStatus()
end

function DreamAdventuresMapDialog:InitView()
    local index = self:GetSelectedSiteIndex()
    if index then
        self:SiteNodeOnClickHandler(index)
    end
end
--endregion init

--region handler
---道具更新事件处理
function DreamAdventuresMapDialog:ItemUpdateEventHandler()
    self:RefreshInfoView()
end

---关闭按钮回调
function DreamAdventuresMapDialog:BtnCloseOnClickHandler()
    if self:GetViewState() == ViewState.CHAPTER then return end
    UIModule.BackDialog()
end

---前往按钮点击回调
function DreamAdventuresMapDialog:BtnGoOnClickHandler()
    if self:GetViewState() == ViewState.MAP then return end

    local data = self:GetQuestData()[self:GetSelectedStageIndex()]
    local isGet = data.status == DreamAdventuresConstants.QuestStatus.PASS
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting6182, "DreamAdventuresPlotVo", data.id)
    DreamAdventuresMgr:SaveMapStatus(self:GetSelectedSiteIndex(), self:GetSelectedStageIndex())
    if checkInt(data.type) == 1 then
        -- 纯剧情
        DreamAdventuresMgr:PlayingPlot(vo.plotIdStory, function ()
            if not isGet then
                local activityId = DreamAdventuresMgr:GetActivityId()
                GameUtils.Request(Interfaces.DreamAdventuresPlot, {activityUuid = activityId, questId = vo.id}, Bind(self, self.PlotResponseHandler))
            end
        end)
    else
        if isGet then
            DreamAdventuresMgr:PlayingPlot(vo.plotIdWave, function ()
                DreamAdventuresMgr:PlayingPlot(vo.plotIdEndWave)
            end)
            return
        end
        -- 开始战斗
        local activityId = DreamAdventuresMgr:GetActivityId()
        UIModule.OpenDialog({ id = Constants.UITypeIds.UIFightTeamChoose, parameters = { levelId = data.id, activityUuid = activityId } }, {
            { id = Constants.UITypeIds.ActivityDreamAdventureslStoryMap },
        })
    end
    
end

---地点点击回调
---@param index number 
function DreamAdventuresMapDialog:SiteNodeOnClickHandler(index)
    if self:GetViewState() == ViewState.CHAPTER then return end

    local siteData = DreamAdventuresMgr:GetMapQuest()[index]
    if not siteData then return end

    if checkInt(siteData.unlockCountdown) > 0 then
        local text = string.format(localize("距离开放：_num_", {_num_ =CfUtils.GetTimeHMS10(checkInt(siteData.unlockCountdown + DreamAdventuresMgr:GetEnterTimestamp() - os.time()))}))
        GameUtils.Toast(text)
        return 
    elseif checkInt(siteData.status) == 0 then
        GameUtils.Toast(localize('通关上一个地点后解锁'))
        return 
    end
    
    self:SetSelectedSiteIndex(index)
    self._selectedStageIndex = nil
    self:PlayEnterChapterAnimation(index)
    self:SetViewState(ViewState.CHAPTER)
    self:RefreshChapterView(siteData)
    self:RefreshInfoView(siteData)
end

---关卡列表cell处理
function DreamAdventuresMapDialog:OnGetItemByIndex(listView, idx)
    local index = idx + 1
    local cell = listView:NewListViewItem("Cell")
    local scr = CfUtils.GetLuaScr(cell, DreamAdventuresConstants.ScrPath.MapStageListCell)
    if not isNull(scr) then
        local data = self:GetQuestData()[index]
        scr:RefreshCell(data, self:GetSelectedStageIndex() == index, index)
        scr:SetClickCB(Bind(self, self.CellOnClickHandler))
    end
    return cell
end

---关卡列表点击回调
function DreamAdventuresMapDialog:CellOnClickHandler(index)
    if self:GetViewState() == ViewState.MAP then return end
    if index == self:GetSelectedStageIndex() then return end
    
    self:SetSelectedStageIndex(index)
    self:RefreshStageList()
    self:RefreshInfoView()
end

---观看主线剧情response处理
function DreamAdventuresMapDialog:PlotResponseHandler(request, response)
    if checkNumber(response.errCode) ~= 0 then return end

    local jsonData = response.data
    local rewards = jsonData.rewards
    if #rewards > 0 then
        GoodsUtils.DrawRewards(rewards)
        UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })
    end
    DreamAdventuresMgr:SetMainQuestId(jsonData.newMainQuestId)
    --local index = self:GetSelectedSiteIndex()
    --local siteData = DreamAdventuresMgr:GetMapQuest()[index]
    --self:RefreshChapterView(siteData)
    --self:RefreshInfoView()
    CfUtils.SetActive(self.ChapterNode, false)
    self:SetViewState(ViewState.MAP)
    self._selectedStageIndex = nil
    self:InitData()
    self:InitView()
end
--endregion handler

--region private
---播放进入章节动画
function DreamAdventuresMapDialog:PlayEnterChapterAnimation(index)
    if self._aniCo ~= nil then
        cs_coroutine.stop(self._aniCo)
    end
    self._aniCo = cs_coroutine.start(function()
        UIRaycastBlocker:AddCondition("DreamAdventuresMapDialogAni")
        CfUtils.SetActive(self.ChapterNode, true)
        local animName = string.format("ActivityDreamAdventureslStoryMap_MapToChapter_%d_%s", index, SiteDefine[index])
        CfUtils.PlayAnimation(self.Root, animName, true)
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.6))
        local hpGoodsId = DreamAdventuresMgr:GetActivityHPId()
        CfUtils.RefreshTopCommon(function()
            self:SetViewState(ViewState.MAP)
            self:PlayExitChapterAnimation(index)
            CfUtils.SetTopCommonActive( false, false)
            CfUtils.ResetNavigatorCustomBackAction()
        end, true, true, {hpGoodsId})
        UIRaycastBlocker:RemoveCondition("DreamAdventuresMapDialogAni")
    end)
end

---播放退出章节动画
function DreamAdventuresMapDialog:PlayExitChapterAnimation(index)
    if self._aniCo ~= nil then
        cs_coroutine.stop(self._aniCo)
    end
    self._aniCo = cs_coroutine.start(function()
        UIRaycastBlocker:AddCondition("DreamAdventuresMapDialogAni")
        local animName = string.format("ActivityDreamAdventureslStoryMap_ChapterToMap_%d_%s", index, SiteDefine[index])
        CfUtils.PlayAnimation(self.Root, animName, true)
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.6))
        UIRaycastBlocker:RemoveCondition("DreamAdventuresMapDialogAni")
    end)
end

---刷新章节页面
function DreamAdventuresMapDialog:RefreshChapterView(siteData)
    local questData = self:GetQuestListByPlaceId(siteData.questId)
    self:SetQuestData(questData)
    
    local showIndex = 0
    if self:GetSelectedStageIndex() then
        showIndex = self:GetSelectedStageIndex()
    else
        for idx,v in pairs(questData) do
            if v.status == DreamAdventuresConstants.QuestStatus.NOW then
                showIndex = idx
                self:SetSelectedStageIndex(idx)
                break
            end
        end
        if showIndex == 0 then
            showIndex = #questData
            self:SetSelectedStageIndex(showIndex)
        end
    end

    self:RefreshStageList()
    self.ChapterLeftTabItem:MovePanelToItemIndex(showIndex - 1)
end

---刷新地点
function DreamAdventuresMapDialog:RefreshSiteNode()
    self._siteNodeScrList = {}
    for i, v in ipairs(SiteDefine) do
        local node = self.MapNodeRoot:Find(string.format("Container/ButtonItem%d", i))
        if isNotNull(node) then
            ---@type DreamAdventuresMapSiteNode
            local scr = CfUtils.GetLuaScr(node, DreamAdventuresConstants.ScrPath.MapSiteNode)
            if scr then
                scr:InitNode(i)
                table.insert(self._siteNodeScrList, scr)
            end
        end
    end
end

---刷新关卡列表
function DreamAdventuresMapDialog:RefreshStageList()
    local questData = self:GetQuestData()
    if not self.ChapterLeftTabItem.IsListViewInit then
        self.ChapterLeftTabItem:InitListView(#questData, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.ChapterLeftTabItem, #questData)
    end
end

---刷新关卡详情页面
function DreamAdventuresMapDialog:RefreshInfoView()
    local data = self:GetQuestData()[self:GetSelectedStageIndex()]
    if not data then return end
    
    local isGet = data.status == DreamAdventuresConstants.QuestStatus.PASS
    local isStory = data.isStory
    local rewardsVo = CfUtils.GetCfVo(AutoIds.IdSetting6189, "DreamAdventuresMainRewardsVo", data.id)
    local rewards = {}
    if next(rewardsVo) ~= nil then
        for i, goodsId in ipairs(rewardsVo.showItem) do
            local t = {
                goodsId = goodsId,
                num = rewardsVo.showItemNum[i]
            }
            table.insert(rewards, t)
        end
    end

    local scr = CfUtils.GetLuaScr(self.CommonGoodsListLight,  DreamAdventuresConstants.ScrPath.CommonGoodsListLight)
    scr:FreshBaseUI(rewards, false, isGet)

    CfUtils.FillText(self.InfoTextDesc, data.desc)
    CfUtils.SetActive(self.InfoRewardNode, not isStory)

    if isStory then
        CfUtils.SetActive(self.CommonBtnConsumePop, false)
    else
        UICommonUtils.FillCommonBtnConsumePop(self.CommonBtnConsumePop, data.costItem, data.costNum)
        CfUtils.SetActive(self.CommonBtnConsumePop, not isGet)
    end
    local fontStyleBtn = KTool.GetComponent(self.BtnGo.gameObject ,typeof(CS.Game.Native.Common.FontStyleButton) )
    if isGet then
        fontStyleBtn:ResetFontStyle("B5" , localize("回顾剧情"))
        CfUtils.SetActive(self.BtnGo, data.type ~= 0)
    else
        local btnName = isStory and localize("阅读") or localize("前往战斗")
        fontStyleBtn:ResetFontStyle("B3" , btnName)
        CfUtils.SetActive(self.BtnGo, true)
    end
end
