---通过placeId获取当前位置的关卡数据
function DreamAdventuresMapDialog:GetQuestListByPlaceId(placeId)
    local contentId = DreamAdventuresMgr:GetActivityContentId()
    local conf = CfUtils.GetCf(AutoIds.IdSetting6186, "DreamAdventuresQuestPlotVo", true)
    local questData = {}
    for _, v in ipairs(conf) do
        if checkInt(v.activityId) == contentId and checkInt(v.placeId) == checkInt(placeId) then
            table.insert(questData, clone(v))
        end
    end
    table.sort(questData, function(a, b) 
        return checkInt(a.id) < checkInt(b.id)
    end)

    local isNew = true
    local mainQuestId = DreamAdventuresMgr:GetMainQuestId()
    for _, questLevel in ipairs(questData) do
        local questLevelVo = questLevel
        if mainQuestId < questLevelVo.id then
            if isNew then
                isNew = false
                questLevelVo.status = DreamAdventuresConstants.QuestStatus.NOW -- 新解锁
            else
                questLevelVo.status = DreamAdventuresConstants.QuestStatus.LOCK -- 锁定
            end
        else
            questLevelVo.status = DreamAdventuresConstants.QuestStatus.PASS -- 已通关
        end
        questLevelVo.isStory = checkInt(questLevelVo.type) == DreamAdventuresConstants.QuestPlotType.STORY
    end
    return questData
end

---获取最新关卡状态
function DreamAdventuresMapDialog:GetNewQuestStatus()
    local id = DreamAdventuresMgr:GetMainQuestId()
    local contentId = DreamAdventuresMgr:GetActivityContentId()
    local mapQuest = DreamAdventuresMgr:GetMapQuest()
    local conf = CfUtils.GetCf(AutoIds.IdSetting6186, "DreamAdventuresQuestPlotVo", true)
    local data = nil
    for _, v in ipairs(conf) do
        if checkInt(v.unlockLevel) == checkInt(id) then
            data = v
            break
        end
    end
    if not data then
        ---最后一关
        for i, v in ipairs(mapQuest) do
            if checkInt(v.status) == 1 then
                v.status = 2
            end
        end
        self:RefreshSiteNode()
        return 
    end
    
    local placeId = checkInt(data.placeId)
    local siteIndex = nil
    local mapQuestData = nil
    for i, v in ipairs(mapQuest) do
        if v.questId == placeId then
            siteIndex = i
            mapQuestData = v
            break
        end
    end

    if not DreamAdventuresMgr:CheckSiteOpenTime(mapQuestData.unlockCountdown) then
        for i, v in ipairs(mapQuest) do
            if checkInt(v.status) == 1 then
                v.status = 2
            end
        end
        self:RefreshSiteNode()
        return DreamAdventuresMgr:GetMapStatus()
    end

    if checkInt(mapQuestData.status) == 0 then
        for i, v in ipairs(mapQuest) do
            if checkInt(v.status) == 1 then
                v.status = 2
            end
        end
        mapQuestData.status = 1
        self:RefreshSiteNode()
    end
    
    local questData = {}
    for _, v in ipairs(conf) do
        if checkInt(v.activityId) == contentId and checkInt(v.placeId) == placeId then
            table.insert(questData, clone(v))
        end
    end
    table.sort(questData, function(a, b)
        return checkInt(a.id) < checkInt(b.id)
    end)
    local stageIndex = nil
    for i, v in ipairs(questData) do
        if checkInt(id) == checkInt(v.unlockLevel) then
            stageIndex = i
        end
    end
    return siteIndex, stageIndex
end
